              </button>
            </div>
          </div>
          <div className="app__mode-header">
            <span className="app__mode-title">{t('editorMode')}</span>
          </div>
          {errorMessage && (
            <ErrorMessage message={errorMessage} onDismiss={() => setError(null)} />
